import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class OrderServiceLegacy {
  private final OrderRepository repo;

  public OrderServiceLegacy(OrderRepository repo) {
    this.repo = repo;
  }

  @Transactional
  public void touchOrderTwice() {
    // ❌ OLD: within ONE transaction, the second find hits the L1
    // (PersistenceContext) — fine. But across transactions / requests
    // (or if the session is fresh), every find is a DB round trip:
    Order o1 = repo.findById(1L).orElseThrow(); // ❌ OLD: SQL (new tx)
    Order o2 = repo.findById(1L).orElseThrow(); // ❌ OLD: SQL again
    // For a hot entity read by thousands of requests, this hammering
    // the DB is the cost that a second-level cache removes.
  }
}

