import jakarta.persistence.Entity;
import org.hibernate.annotations.Cache;
import org.hibernate.annotations.CacheConcurrencyStrategy;

// ✅ NEW: mark the entity cacheable so reads are served from the
// shared second-level cache across transactions (configured with
// spring.jpa.properties.hibernate.cache.use_second_level_cache=true
// and a provider such as Ehcache).
@Entity
@Cacheable // ✅ NEW: opt into L2 caching
@Cache(usage = CacheConcurrencyStrategy.READ_WRITE) // ✅ NEW: strategy
public class Order {
  // ... fields
}

// ✅ NEW: repeated findById across transactions now hits L2 after the
// first load — no DB round trip for the cached entity.
// When the entity is updated and flushed, Hibernate invalidates its
// L2 region so other sessions reload fresh data.

// Note: L1 (PersistenceContext) still provides identity within a
// transaction automatically; L2 is the cross-session shared cache.
